DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030191625_DisbursementInvoiceUpload') THEN
    CREATE TABLE "ADM_RATE_INDEX_VALUES" (
        "RATE_VALUE_ID" bigint GENERATED BY DEFAULT AS IDENTITY,
        "RATE_INDEX_ID" bigint NOT NULL,
        "EFFECTIVE_FROM_DATE" date NOT NULL,
        "EFFECTIVE_TO_DATE" date,
        "ANNUAL_RATE_PCT" numeric(9,6) NOT NULL,
        "CREATED_BY" character varying(100) NOT NULL,
        "CREATED_AT" timestamp with time zone NOT NULL,
        "UPDATED_BY" character varying(100),
        "UPDATED_AT" timestamp with time zone,
        "ROW_VERSION" integer NOT NULL,
        CONSTRAINT "PK_ADM_RATE_INDEX_VALUES" PRIMARY KEY ("RATE_VALUE_ID"),
        CONSTRAINT "FK_ADM_RATE_INDEX_VALUES_ADM_RATE_INDEXES" FOREIGN KEY ("RATE_INDEX_ID") REFERENCES "ADM_RATE_INDEXES" ("RATE_INDEX_ID") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

