DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030191625_DisbursementInvoiceUpload') THEN
    UPDATE "WFE_WORKFLOW_DEFINITIONS"
       SET "BPMN_XML" = replace("BPMN_XML",
           'finova:stepCode="INVOICE_UPLOAD" finova:stepType="HumanTask" finova:assignmentType="Role" finova:assignee="OPERATIONS_OFFICER" finova:route="crm-disbursement-request"',
           'finova:stepCode="INVOICE_UPLOAD" finova:stepType="HumanTask" finova:assignmentType="Role" finova:assignee="OPERATIONS_OFFICER" finova:route="crm-disbursement-invoice-entry"')
     WHERE "WORKFLOW_CODE" = 'DISBURSEMENT_REQUEST_WF';
    UPDATE "WFE_TASKS" t SET "ROUTE" = 'crm-disbursement-invoice-entry'
      FROM "WFE_STEP_INSTANCES" s
      JOIN "WFE_WORKFLOW_INSTANCES" i ON i."WORKFLOW_INSTANCE_ID" = s."WORKFLOW_INSTANCE_ID"
      JOIN "WFE_WORKFLOW_DEFINITIONS" w ON w."WORKFLOW_DEFINITION_ID" = i."WORKFLOW_DEFINITION_ID"
     WHERE t."STEP_INSTANCE_ID" = s."STEP_INSTANCE_ID" AND s."STEP_CODE" = 'INVOICE_UPLOAD'
       AND w."WORKFLOW_CODE" = 'DISBURSEMENT_REQUEST_WF' AND t."ROUTE" = 'crm-disbursement-request';
    UPDATE "WFE_INBOX" x SET "ROUTE" = 'crm-disbursement-invoice-entry'
      FROM "WFE_STEP_INSTANCES" s
      JOIN "WFE_WORKFLOW_INSTANCES" i ON i."WORKFLOW_INSTANCE_ID" = s."WORKFLOW_INSTANCE_ID"
      JOIN "WFE_WORKFLOW_DEFINITIONS" w ON w."WORKFLOW_DEFINITION_ID" = i."WORKFLOW_DEFINITION_ID"
     WHERE x."STEP_INSTANCE_ID" = s."STEP_INSTANCE_ID" AND s."STEP_CODE" = 'INVOICE_UPLOAD'
       AND w."WORKFLOW_CODE" = 'DISBURSEMENT_REQUEST_WF' AND x."ROUTE" = 'crm-disbursement-request';
    END IF;
END $EF$;

